import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync, copyFileSync, mkdirSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { tmpdir } from "node:os";

// runCheck tracks one generated file in a scratch repository, lets setup add
// its sources, and returns the checker's exit code and output.
// With generated = true the file is an untracked, ignored mirror: git lists it only for the
// `--others` listing, as it does for AGENTS.md, .codex/** and .opencode/**.
const runCheck = (file, header, setup, generated = false) => {
  const root = mkdtempSync(join(tmpdir(), "marker-test-"));
  try {
    copyFileSync(new URL("./check-codex-markers.mjs", import.meta.url), join(root, "check.mjs"));
    mkdirSync(join(root, "bin"));
    writeFileSync(join(root, "bin/git"), `#!/bin/sh\ncase "$*" in *--others*) ${generated ? `printf '${file}\\0'` : ":"} ;; *) ${generated ? ":" : `printf '${file}\\0'`} ;; esac\n`, { mode: 0o755 });
    mkdirSync(dirname(join(root, file)), { recursive: true });
    writeFileSync(join(root, file), header);
    setup(root);
    const result = spawnSync(process.execPath, [join(root, "check.mjs")], {
      cwd: root,
      env: { ...process.env, PATH: `${join(root, "bin")}:${process.env.PATH}` },
      encoding: "utf8",
    });
    return { code: result.status, output: result.stdout + result.stderr };
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
};

for (const marker of [
  "Generated by engine-sync from source.md — edit the source, then run: engine-sync build",
  "Generated by pfm codex build from source.md; do not edit",
]) {
  for (const live of [true, false]) {
    test(`${marker}: source ${live ? "live" : "missing"}`, () => {
      const { code, output } = runCheck("mirror.md", `<!-- ${marker} -->\n`, (root) => {
        if (live) writeFileSync(join(root, "source.md"), "source\n");
      });
      assert.equal(code, live ? 0 : 1, output);
      if (!live) assert.match(output, /mirror\.md.*source\.md/);
    });
  }
}

// The OpenCode config names its writer and an optional co-source: with no
// .mcp.json the writer alone keeps the file live.
test("engine-sync opencode build + .mcp.json: writer only", () => {
  const header =
    "// Generated by engine-sync from engine-sync opencode build + .mcp.json — edit the source, then run: engine-sync build\n{}\n";
  const { code, output } = runCheck("opencode.jsonc", header, () => {});
  assert.equal(code, 0, output);
});

// The mirrors engine-sync writes are untracked: the orphan reconcile has to read them on disk, or it
// examines nothing and still reports a clean claim.
for (const [file, header] of [
  [".codex/agents/role.toml", "# Generated by engine-sync from .claude/agents/role.md — edit the source, then run: engine-sync build\nname = \"role\"\n"],
  [".opencode/agent/role.md", "---\n# Generated by engine-sync from .claude/agents/role.md — edit the source, then run: engine-sync build\ndescription: x\n---\n"],
  ["AGENTS.md", "<!-- Generated by engine-sync from CLAUDE.md — edit the source, then run: engine-sync build -->\n# Root\n"],
]) {
  const source = file === "AGENTS.md" ? "CLAUDE.md" : ".claude/agents/role.md";
  const put = (root) => { mkdirSync(join(root, source, ".."), { recursive: true }); writeFileSync(join(root, source), "source\n"); };
  test(`generated mirror ${file}: source live is counted as examined`, () => {
    const { code, output } = runCheck(file, header, put, true);
    assert.equal(code, 0, output);
    assert.match(output, /1 marked file\(s\) \(0 tracked, 1 generated mirror\)/);
  });
  test(`generated mirror ${file}: source missing is an ORPHAN`, () => {
    const { code, output } = runCheck(file, header, () => {}, true);
    assert.equal(code, 1, output);
    assert.match(output, new RegExp(`ORPHAN ${file.replace(".", "\\.")} — none of its declared sources exist`));
  });
}

test("no generated mirror on disk is named, never a quiet clean claim", () => {
  const { code, output } = runCheck("plain.md", "no marker here\n", () => {});
  assert.equal(code, 0, output);
  assert.match(output, /WARN generated mirrors: none present on disk/);
  assert.match(output, /generate them first: engine-sync codex build \. and engine-sync opencode build \./);
  assert.doesNotMatch(output, /engine-sync build/);
  assert.match(output, /0 marked file\(s\) \(0 tracked, 0 generated mirror\)/);
});

// This enumeration contract needs real Git: the earlier stubs test the marker
// parser but cannot pin which ignored nested paths its pathspec actually lists.
test("ignored nested workbench mirrors are checked by real Git", () => {
  const root = mkdtempSync(join(tmpdir(), "marker-nested-test-"));
  try {
    const env = { ...process.env };
    for (const key of ["GIT_DIR", "GIT_WORK_TREE", "GIT_COMMON_DIR", "PFM_DEV_REPO_GIT_DIR", "PFM_DEV_REPO_WORK_TREE"])
      delete env[key];
    execFileSync("git", ["init", "-q", root], { env });
    writeFileSync(join(root, ".gitignore"), "**/.codex/\n**/.opencode/\n");
    execFileSync("git", ["-C", root, "add", ".gitignore"], { env });
    copyFileSync(new URL("./check-codex-markers.mjs", import.meta.url), join(root, "check.mjs"));
    const paths = ["bench/.codex/agents/ghost.toml", "bench/.opencode/agent/ghost.md"];
    for (const file of paths) {
      mkdirSync(dirname(join(root, file)), { recursive: true });
      writeFileSync(join(root, file), "# Generated by engine-sync from missing-role.md — edit the source, then run: engine-sync build\n");
    }
    const result = spawnSync(process.execPath, [join(root, "check.mjs")], { cwd: root, env, encoding: "utf8" });
    const output = result.stdout + result.stderr;
    assert.equal(result.status, 1, output);
    for (const file of paths) assert.ok(output.includes(`ORPHAN ${file}`), output);
    assert.match(output, /2 generated mirror file\(s\) read/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
